function countdowns(){const tick=()=>{const now=Date.now();document.querySelectorAll('.countdown[data-time]').forEach(el=>{const target=Number(el.dataset.time||0);if(!target||!Number.isFinite(target))return;if(el.closest('.is-live'))return;const diff=target-now;if(diff<=0){el.textContent='SEGERA DIMULAI';return}const total=Math.floor(diff/1000),h=Math.floor(total/3600),m=Math.floor((total%3600)/60),sec=total%60;el.textContent=`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`})};tick();clearInterval(countdowns._timer);countdowns._timer=setInterval(tick,1000)}
