function setupHomeBannerCarousel(banners,seconds=6){
  if(!Array.isArray(banners)||banners.length<2)return;
  const wrap=document.querySelector('#homeBannerCarousel'),img=document.querySelector('#homeBannerImage'),link=document.querySelector('#homeBannerLink'),dots=[...document.querySelectorAll('[data-banner-dot]')];
  if(!wrap||!img||!link)return;
  let index=0,timer=null;
  const show=i=>{index=(i+banners.length)%banners.length;const b=banners[index]||{};img.src=b.image||'/default-banner.svg';img.alt=b.title||'BOLA UTAMA';link.href=b.url||'#';dots.forEach((d,n)=>d.classList.toggle('active',n===index))};
  const auto=()=>{clearInterval(timer);timer=setInterval(()=>show(index+1),Math.max(3,Number(seconds)||6)*1000)};
  document.querySelector('[data-banner-prev]')?.addEventListener('click',e=>{e.preventDefault();show(index-1);auto()});
  document.querySelector('[data-banner-next]')?.addEventListener('click',e=>{e.preventDefault();show(index+1);auto()});
  dots.forEach(d=>d.addEventListener('click',e=>{e.preventDefault();show(Number(d.dataset.bannerDot)||0);auto()}));
  wrap.addEventListener('mouseenter',()=>clearInterval(timer));wrap.addEventListener('mouseleave',auto);auto();
}
