async function liveStreamsPage(){try{const streams=await loadStreams();state.streams=streams;const leagues=[...new Set(streams.map(x=>x.league_name||x.league).filter(Boolean))].sort(),liveCount=streams.filter(x=>x.match_status==='live').length,upcomingCount=streams.filter(x=>x.match_status==='upcoming').length;app.innerHTML=`<div class="container live-catalog"><div class="page-heading"><div><small>RAPIDAPI • SEPAK BOLA SAJA</small><h1>Live Stream Bola</h1><p>Menampilkan pertandingan sepak bola LIVE dan yang akan datang. MMA, gulat, boxing, basket, dan olahraga lain otomatis dibuang.</p></div><a class="btn" href="/livescore">Live Score</a></div><div class="filters"><input id="liveSearch" placeholder="🔍 Cari tim atau liga..."><select id="liveLeague"><option value="">Semua Liga</option>${leagues.map(x=>`<option>${esc(x)}</option>`).join('')}</select><button class="filter-active" id="liveNow">🔴 Live (${liveCount})</button><button id="liveUpcoming">🕐 Akan Datang (${upcomingCount})</button><button id="liveAll">Semua</button></div><div id="liveGrid" class="cards streams">${streams.map(streamCard).join('')||'<div class="service-empty"><img src="/favicon.svg"><div><b>Belum ada live sepak bola</b><span>Periksa RAPIDAPI_KEY dan endpoint 1xAPI pada Railway Variables.</span></div></div>'}</div></div>`;const cards=()=>[...document.querySelectorAll('#liveGrid .stream-card')],apply=(mode='all')=>{const q=document.querySelector('#liveSearch').value.toLowerCase(),league=document.querySelector('#liveLeague').value.toLowerCase();cards().forEach((x,i)=>{const status=streams[i]?.match_status,searchOk=x.textContent.toLowerCase().includes(q)&&(!league||x.textContent.toLowerCase().includes(league)),statusOk=mode==='all'||status===mode;x.hidden=!(searchOk&&statusOk)})};let mode='all';document.querySelector('#liveSearch').oninput=()=>apply(mode);document.querySelector('#liveLeague').onchange=()=>apply(mode);document.querySelector('#liveNow').onclick=()=>{mode='live';apply(mode)};document.querySelector('#liveUpcoming').onclick=()=>{mode='upcoming';apply(mode)};document.querySelector('#liveAll').onclick=()=>{mode='all';document.querySelector('#liveSearch').value='';document.querySelector('#liveLeague').value='';apply(mode)};apply('all')}catch(e){app.innerHTML=configError(e)}}
function renderScores(list){const streamNames=new Set(state.streams.flatMap(x=>{const t=streamTeams(x);return[t.home.name.toLowerCase(),t.away.name.toLowerCase()]}));const groups=Object.values(list.reduce((a,x)=>{const k=x.league?.id||'x';(a[k]??={league:x.league,rows:[]}).rows.push(x);return a},{}));app.innerHTML=`<div class="container livescore-page">${filterUI()}<div class="layout3"><aside class="sidebar"><h3>Top Liga</h3>${topLeagues.map(x=>`<a href="/klasemen?league=${x[0]}">${x[1]}</a>`).join('')}</aside><main>${groups.map(g=>`<section class="league-group"><div class="league-head"><img src="${esc(g.league?.logo||'/favicon.svg')}"><div><b>${esc(g.league?.name)}</b><small>${esc(g.league?.country||'')}</small></div></div>${g.rows.map(x=>scoreRow(x,streamNames)).join('')}</section>`).join('')||'<div class="empty">Tidak ada pertandingan</div>'}</main><aside class="standings"><h3>Klasemen Liga</h3><p>Lihat tabel lengkap, jadwal, dan performa tim.</p><a class="btn" href="/klasemen">Buka Klasemen</a></aside></div></div>`;document.querySelector('#apply').onclick=async()=>{try{const next=await loadFixtures('date='+document.querySelector('#date').value);state.fixtures=next;renderScores(next)}catch(e){alert(e.message)}};document.querySelector('#search').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.score-row').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))};document.querySelectorAll('[data-status]').forEach(b=>{b.onclick=()=>renderScores(state.fixtures.filter(x=>b.dataset.status==='all'||(b.dataset.status==='live'?['1H','2H','HT','ET','P'].includes(x.fixture?.status?.short):x.fixture?.status?.short===b.dataset.status)))})}
function scoreRow(x,streams){const f=x.fixture||{},h=x.teams?.home||{},a=x.teams?.away||{},has=streams.has(h.name?.toLowerCase())||streams.has(a.name?.toLowerCase()),score=x.goals?.home==null?'VS':`${x.goals.home} : ${x.goals.away??0}`;return `<a class="score-row" href="/match/${f.id}"><div class="score-meta"><b>${esc(f.status?.short||'NS')}</b><span>${fmtTime(f.date)}</span></div><div class="score-team home-team"><img loading="lazy" decoding="async" src="${esc(h.logo||'/favicon.svg')}"><b>${esc(h.name)}</b></div><strong class="score-pill">${score}</strong><div class="score-team"><img loading="lazy" decoding="async" src="${esc(a.logo||'/favicon.svg')}"><b>${esc(a.name)}</b></div>${has?'<span class="live-btn">▣ Live</span>':'<span></span>'}</a>`}
async function predictions(){app.innerHTML='<div class="loading"><span></span> Memuat prediksi...</div>';try{let fixtures=await loadFixtures(futureRange(5));fixtures=fixtures.slice(0,20);const enriched=await Promise.all(fixtures.map(async x=>{try{const p=await api('/api/football/predictions?fixture='+x.fixture.id);return{x,p:p.response?.[0]}}catch{return{x,p:null}}}));app.innerHTML=`<div class="container prediction-page"><h1>Prediksi Bola</h1><div class="cards prediction-top">${fixtures.slice(0,5).map(x=>fixtureCard(x,'prediction-card')).join('')}</div><div class="prediction-intro"><h2>Prediksi Pertandingan Mendatang</h2><p>Persentase berasal dari API-FOOTBALL berdasarkan performa, perbandingan tim, dan statistik pertandingan.</p></div><div class="filters"><input id="predSearch" placeholder="🔍 Cari tim atau liga..."></div>${Object.values(enriched.reduce((a,z)=>{const k=z.x.league?.name||'Liga';(a[k]??=[]).push(z);return a},{})).map(g=>`<section class="prediction-group"><div class="league-head"><img src="${esc(g[0].x.league.logo||'/favicon.svg')}"> ${esc(g[0].x.league.name)}</div>${g.map(predRow).join('')}</section>`).join('')||'<div class="service-empty"><img src="/favicon.svg"><div><b>Prediksi belum tersedia</b><span>Tidak ada pertandingan dalam rentang tanggal ini.</span></div></div>'}</div>`;document.querySelector('#predSearch')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.pred-row').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))})}catch(e){app.innerHTML=configError(e)}}
function formHTML(s=''){return `<div class="form">${String(s||'').slice(0,5).split('').filter(x=>/[WDL]/.test(x)).map(x=>`<i class="${x}">${x}</i>`).join('')}</div>`} function predRow({x,p}){const ph=Math.max(0,Number(String(p?.predictions?.percent?.home||'0').replace('%',''))),pd=Math.max(0,Number(String(p?.predictions?.percent?.draw||'0').replace('%',''))),pa=Math.max(0,Number(String(p?.predictions?.percent?.away||Math.max(0,100-ph-pd)).replace('%',''))),total=ph+pd+pa||100,hp=Math.round(ph/total*100),dp=Math.round(pd/total*100),ap=100-hp-dp,home=x.teams.home,away=x.teams.away;return `<a class="prediction-row pred-row" href="/match/${x.fixture.id}"><div class="prediction-team"><img src="${esc(home.logo)}"><b>${esc(home.name)}</b></div><div class="prediction-center"><time>${fmtDate(x.fixture.date)} • ${fmtTime(x.fixture.date)}</time><strong>${p?.predictions?.goals?.home??'-'} : ${p?.predictions?.goals?.away??'-'}</strong><small>${esc(p?.predictions?.advice||'Prediksi belum diterbitkan')}</small></div><div class="prediction-team"><img src="${esc(away.logo)}"><b>${esc(away.name)}</b></div><div class="prob"><span class="home" style="width:${hp}%">Home ${hp}%</span><span class="draw" style="width:${dp}%">Draw ${dp}%</span><span class="away" style="width:${ap}%">Away ${ap}%</span></div></a>`}
async function standings(){const q=new URLSearchParams(location.search),league=q.get('league');if(league)return leagueDetail(league);app.innerHTML='<div class="loading"><span></span> Memuat liga...</div>';try{const d=await api('/api/football/leagues?current=true');state.leagues=d.response||[];const countries=Object.values(state.leagues.reduce((a,x)=>{const k=x.country?.name||'World';(a[k]??={name:k,flag:x.country?.flag,items:[]}).items.push(x);return a},{})).sort((a,b)=>a.name.localeCompare(b.name));app.innerHTML=`<div class="container standings-page"><div class="page-heading"><div><small>DATA KOMPETISI</small><h1>Klasemen Sepak Bola</h1><p>Pilih liga populer atau telusuri semua kompetisi berdasarkan negara.</p></div><select class="field"><option>Sepak Bola</option><option>Bola Basket</option><option>Tenis</option></select></div><div class="cards league-cards">${leagueCards()}</div><div class="country-heading"><h2>Semua Liga</h2><input class="field" id="leagueSearch" placeholder="🔍 Cari liga atau negara..."></div><div id="countries" class="countries">${countries.map(c=>`<details class="panel country"><summary>${c.flag?`<img src="${c.flag}">`:''}<b>${esc(c.name)}</b><span>${c.items.length} liga</span><i>⌄</i></summary><div class="country-leagues">${c.items.map(x=>`<a href="/klasemen?league=${x.league.id}"><img src="${esc(x.league.logo||'/favicon.svg')}"><span>${esc(x.league.name)}</span><b>›</b></a>`).join('')}</div></details>`).join('')}</div></div>`;document.querySelector('#leagueSearch').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.country').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(q))}}catch(e){app.innerHTML=configError(e)}}
async function leagueDetail(id){app.innerHTML='<div class="loading"><span></span> Memuat klasemen...</div>';try{const season=new Date().getFullYear(),[st,fx]=await Promise.all([api(`/api/football/standings?league=${id}&season=${season}`).catch(()=>({response:[]})),api(`/api/football/fixtures?league=${id}&season=${season}&next=20`).catch(()=>({response:[]}))]);const league=st.response?.[0]?.league,table=league?.standings?.[0]||[];app.innerHTML=`<div class="container"><a class="btn" href="/klasemen">‹ Kembali</a><div class="layout3" style="grid-template-columns:460px 1fr;margin-top:25px"><section><h1>${esc(league?.name||'Kompetisi')}</h1><div class="league-group"><div class="league-head">Pertandingan</div>${(fx.response||[]).map(x=>scoreRow(x,new Set())).join('')||'<p>Belum ada pertandingan</p>'}</div></section><section class="panel"><h3>Liga</h3>${table.length?standTable(table):'<div class="empty">Klasemen belum tersedia. Kompetisi ini mungkin menggunakan sistem knockout.</div>'}</section></div></div>`}catch(e){app.innerHTML=configError(e)}}
function standTable(rows){return `<div style="overflow:auto"><table class="table"><thead><tr><th>#</th><th>Tim</th><th>PL</th><th>W</th><th>D</th><th>L</th><th>GD</th><th>PTS</th><th>FORM</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.rank}</td><td><img width="24" src="${r.team.logo}"> ${esc(r.team.name)}</td><td>${r.all.played}</td><td>${r.all.win}</td><td>${r.all.draw}</td><td>${r.all.lose}</td><td>${r.goalsDiff}</td><td><b>${r.points}</b></td><td>${formHTML(r.form||'')}</td></tr>`).join('')}</tbody></table></div>`}
function news(){const arts=state.boot.articles;app.innerHTML=`<div class="container"><h1>Berita Olahraga</h1><div class="filters"><button class="filter-active">Semua</button><button>Sepak Bola</button><button>Bola Basket</button><button>Voli</button><button>Tenis</button></div><div class="news-grid">${arts.map(newsCard).join('')||'<div class="empty">Berita dikelola melalui Admin.</div>'}</div></div>`}
function renderArticleBody(content){
  const text=String(content||'').replace(/\r\n/g,'\n'),parts=text.split(/(\[\[image:[^\]]+\]\])/gi),out=[];
  for(const part of parts){if(!part)continue;const m=part.match(/^\[\[image:([^\]|]+)(?:\|([^\]]+))?\]\]$/i);if(m){const url=String(m[1]||'').trim();if(/^\/?uploads\//.test(url)||/^https?:\/\//i.test(url)){out.push(`<figure class="article-inline-image"><img loading="lazy" src="${esc(url)}" alt="${esc(m[2]||'Foto artikel')}">${m[2]?`<figcaption>${esc(m[2])}</figcaption>`:''}</figure>`)}continue}const paras=part.split(/\n{2,}/).map(x=>x.trim()).filter(Boolean);for(const para of paras){const lines=para.split('\n').map(x=>esc(x.trim())).filter(Boolean);if(lines.length)out.push(`<p>${lines.join('<br>')}</p>`)}}return out.join('')||'<p>Isi artikel belum tersedia.</p>'
}
function article(slug){const a=state.boot.articles.find(x=>(x.slug||x.id)===slug);if(!a)return app.innerHTML='<div class="empty">Artikel tidak ditemukan.</div>';app.innerHTML=`<article class="container article article-natural"><header class="article-head"><small>Berita Olahraga / ${esc(a.category||'Sepak Bola')}</small><h1>${esc(a.title)}</h1><div class="article-meta">${a.author?`<span>${esc(a.author)}</span>`:''}${a.publishedAt?`<time>${fmtDate(a.publishedAt)}</time>`:''}</div>${a.excerpt?`<p class="article-excerpt">${esc(a.excerpt)}</p>`:''}</header>${a.image?`<figure class="article-cover"><img src="${esc(a.image)}" alt="${esc(a.title)}"></figure>`:''}<div class="article-content">${renderArticleBody(a.content)}</div><div class="tags">${String(a.tags||'').split(',').filter(Boolean).map(t=>`<span>#${esc(t.trim())}</span>`).join('')}</div><h2>Artikel Terkait</h2><div class="news-grid">${state.boot.articles.filter(x=>x.id!==a.id).slice(0,4).map(newsCard).join('')}</div></article>`}

function matchStatusDone(f){return ['FT','AET','PEN'].includes(f?.fixture?.status?.short)}
function detailEvents(rows){if(!rows.length)return '<div class="detail-empty">Ringkasan pertandingan belum tersedia.</div>';return `<div class="detail-events">${rows.map(e=>`<div class="event-row"><b>${esc(e.time?.elapsed??'')}\'</b><span>${esc(e.team?.name||'')}</span><strong>${esc(e.player?.name||e.detail||e.type||'')}</strong></div>`).join('')}</div>`}
function detailStatistics(rows){if(!rows.length)return '<div class="detail-empty">Statistik belum tersedia.</div>';const [h,a]=rows;const hm=new Map((h?.statistics||[]).map(x=>[x.type,x.value])),am=new Map((a?.statistics||[]).map(x=>[x.type,x.value])),keys=[...new Set([...hm.keys(),...am.keys()])];return `<div class="stats-compare"><header><b>${esc(h?.team?.name||'Home')}</b><b>STATISTIK</b><b>${esc(a?.team?.name||'Away')}</b></header>${keys.map(k=>`<div><span>${esc(hm.get(k)??'-')}</span><b>${esc(k)}</b><span>${esc(am.get(k)??'-')}</span></div>`).join('')}</div>`}
function lineupSide(row,side){const xi=row?.startXI||[];return `<div class="pitch-side ${side}">${xi.map((x,i)=>{const p=x.player||{},grid=String(p.grid||''),parts=grid.split(':').map(Number),r=parts[0]||Math.floor(i/3)+1,c=parts[1]||((i%3)+1),left=Math.min(90,Math.max(10,(c/5)*100)),top=Math.min(90,Math.max(8,(r/5)*100));return `<div class="pitch-player" style="left:${left}%;top:${top}%"><span>${esc(p.number||'')}</span><b>${esc(p.name||'Pemain')}</b></div>`}).join('')}</div>`}
function detailLineups(rows){if(!rows.length)return '<div class="detail-empty">Susunan pemain belum tersedia.</div>';const h=rows[0],a=rows[1]||{};return `<div class="lineup-head"><b>${esc(h?.formation||'-')}</b><span>FORMASI</span><b>${esc(a?.formation||'-')}</b></div><div class="football-pitch">${lineupSide(h,'home')}${lineupSide(a,'away')}</div>`}
function detailHistory(rows){if(!rows.length)return '<div class="detail-empty">Riwayat pertemuan belum tersedia.</div>';return `<div class="history-list">${rows.map(x=>`<a href="/detail/${esc(x.fixture?.id)}"><time>${fmtDate(x.fixture?.date)}</time><div>${team(x.teams?.home||{})}<strong>${x.goals?.home??'-'} : ${x.goals?.away??'-'}</strong>${team(x.teams?.away||{})}</div></a>`).join('')}</div>`}
async function detailTab(fixture,tab){const box=document.querySelector('#matchDetail');if(!box)return;box.innerHTML='<div class="loading detail-loading"><span></span></div>';try{const id=fixture.fixture.id;if(tab==='summary'){const d=await api(`/api/fixture/${id}/events`);box.innerHTML=detailEvents(d.response||[])}else if(tab==='statistics'){const d=await api(`/api/fixture/${id}/statistics`);box.innerHTML=detailStatistics(d.response||[])}else if(tab==='lineups'){const d=await api(`/api/fixture/${id}/lineups`);box.innerHTML=detailLineups(d.response||[])}else if(tab==='history'){const d=await api(`/api/football/fixtures?h2h=${fixture.teams.home.id}-${fixture.teams.away.id}&last=8`);box.innerHTML=detailHistory(d.response||[])}else if(tab==='standing'){const season=fixture.league.season||new Date(fixture.fixture.date).getFullYear(),d=await api(`/api/football/standings?league=${fixture.league.id}&season=${season}`),rows=d.response?.[0]?.league?.standings?.[0]||[];box.innerHTML=rows.length?standTable(rows):'<div class="detail-empty">Klasemen belum tersedia untuk kompetisi ini.</div>'}}catch(e){box.innerHTML=`<div class="detail-empty">${esc(e.message||'Data belum tersedia.')}</div>`}}
function widgetModal(id){let m=document.querySelector('#widgetModal');if(!m){m=document.createElement('div');m.id='widgetModal';m.className='auth-modal';document.body.appendChild(m)}const url=`${location.origin}/widget/score/${encodeURIComponent(id)}`;m.innerHTML=`<div class="widget-dialog"><button class="modal-x">×</button><h2>Widget URL</h2><p>Silakan copy url dibawah ini.</p><input class="field" id="widgetUrl" readonly value="${esc(url)}"><div><button class="btn modal-close">Tutup</button><button class="btn" id="copyWidget">▣ Salin URL</button></div></div>`;m.classList.add('open');m.querySelector('.modal-x').onclick=m.querySelector('.modal-close').onclick=()=>m.remove();m.querySelector('#copyWidget').onclick=async()=>{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(url).catch(()=>{});else{const el=m.querySelector('#widgetUrl');el.select();document.execCommand?.('copy')}m.querySelector('#copyWidget').textContent='✓ Tersalin'}}
async function matchDetailPage(id){app.innerHTML='<div class="loading"><span></span> Memuat detail pertandingan...</div>';try{const d=await api('/api/football/fixtures?id='+encodeURIComponent(id)),fixture=d.response?.[0];if(!fixture)throw Error('Pertandingan tidak ditemukan');const h=fixture.teams.home,a=fixture.teams.away,done=matchStatusDone(fixture),score=done?`${fixture.goals.home??0} : ${fixture.goals.away??0}`:'VS';app.innerHTML=`<div class="container sarang-detail-page"><div class="detail-actions"><a class="btn" href="/">‹ Kembali</a><button class="btn secondary" id="widgetBtn">▣ Widget</button></div><section class="sarang-match-card panel"><div class="prediction-detail-league"><img src="${esc(fixture.league.logo||'/favicon.svg')}"><div><b>${esc(fixture.league.name)}</b><small>${esc(fixture.league.round||'')}</small></div></div><div class="prediction-detail-date">${fmtDate(fixture.fixture.date)} | ${fmtTime(fixture.fixture.date)} WIB</div><div class="prediction-detail-teams"><div><b>${esc(h.name)}</b><img loading="lazy" decoding="async" src="${esc(h.logo||'/favicon.svg')}"></div><strong>${score}</strong><div><img loading="lazy" decoding="async" src="${esc(a.logo||'/favicon.svg')}"><b>${esc(a.name)}</b></div></div><p class="prediction-detail-status">${esc(fixture.fixture.status?.long||'Scheduled')}</p></section><div class="tabs detail-tabs"><button class="btn active" data-detail-tab="summary">Ringkasan</button><button class="btn" data-detail-tab="statistics">Statistik</button><button class="btn" data-detail-tab="lineups">Susunan Pemain</button><button class="btn" data-detail-tab="history">Riwayat</button><button class="btn" data-detail-tab="standing">Klasemen</button></div><section id="matchDetail" class="panel match-detail"></section></div>`;document.querySelector('#widgetBtn').onclick=()=>widgetModal(id);document.querySelectorAll('[data-detail-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-detail-tab]').forEach(x=>x.classList.toggle('active',x===b));detailTab(fixture,b.dataset.detailTab)});detailTab(fixture,'summary')}catch(e){app.innerHTML=configError(e)}}
async function widgetScorePage(id){document.querySelector('header')?.remove();document.querySelector('footer')?.remove();document.querySelector('.mobile-nav')?.remove();document.body.classList.add('widget-body');app.innerHTML='<div class="loading"><span></span></div>';try{const d=await api('/api/football/fixtures?id='+encodeURIComponent(id)),f=d.response?.[0];if(!f)throw Error('Pertandingan tidak ditemukan');const settings=state.boot?.settings||{},brandLogo=settings.logo||'/favicon.svg',score=`${f.goals.home??'−'} : ${f.goals.away??'−'}`,status=f.fixture.status?.short||'NS';app.innerHTML=`<div class="score-widget sarang-widget"><div class="widget-topline"><span class="widget-league"><img src="${esc(f.league.logo||'/favicon.svg')}" onerror="this.src='/favicon.svg'">${esc(f.league.name)}</span><b>${esc(status)}</b></div><div class="widget-brand">${settings.logo?`<img src="${esc(brandLogo)}" onerror="this.src='/favicon.svg'" alt="BOLA UTAMA">`:`<span class="widget-text-logo"><b>BOLA</b><em>UTAMA</em></span>`}<span class="widget-brand-name">${esc(settings.siteName||'BOLA UTAMA')}</span></div><div class="widget-match">${team(f.teams.home)}<strong>${score}</strong>${team(f.teams.away)}</div><div class="widget-foot"><span>${fmtDate(f.fixture.date)} • ${fmtTime(f.fixture.date)} WIB</span><b>${esc(f.teams.home.name)} vs ${esc(f.teams.away.name)}</b></div></div>`}catch(e){app.innerHTML=`<div class="detail-empty">${esc(e.message)}</div>`}}
function registerModal(){let m=document.querySelector('#registerModal');if(m)m.remove();m=document.createElement('div');m.id='registerModal';m.className='auth-modal';m.innerHTML=`<div class="auth-card panel modal-register"><button class="modal-x">×</button><h1>Daftar</h1><form id="modalRegisterForm"><input class="field" name="displayName" placeholder="Nama lengkap" required><input class="field" name="username" placeholder="Username" required><input class="field" type="email" name="email" placeholder="Email"><div class="phone-field"><span>+62</span><input class="field" name="phone" placeholder="Nomor handphone"></div><input class="field" type="password" name="password" minlength="8" placeholder="Kata sandi" required><input class="field" type="password" name="confirm" minlength="8" placeholder="Konfirmasi kata sandi" required><button class="btn">Daftar</button><p id="modalRegisterMsg"></p></form><small>Silakan masuk ke akun Anda, jika sudah berhasil mendaftar.</small></div>`;document.body.appendChild(m);m.querySelector('.modal-x').onclick=()=>m.remove();m.onclick=e=>{if(e.target===m)m.remove()};m.querySelector('#modalRegisterForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.password!==d.confirm)return m.querySelector('#modalRegisterMsg').textContent='Konfirmasi kata sandi tidak sama';delete d.confirm;try{const btn=e.target.querySelector('button[type=submit],button.btn');btn.disabled=true;btn.textContent='Mendaftarkan...';await api('/api/auth/register',{method:'POST',body:JSON.stringify(d)});m.querySelector('#modalRegisterMsg').textContent='Pendaftaran berhasil. Membuka profil...';location.href='/profile'}catch(err){const btn=e.target.querySelector('button[type=submit],button.btn');if(btn){btn.disabled=false;btn.textContent='Daftar'}m.querySelector('#modalRegisterMsg').textContent=err.message}}}
