async function resolveStreamStable(mid,attempts=3){
  let last=null;
  for(let i=0;i<attempts;i++){
    try{const d=await api('/api/stream/resolve/'+encodeURIComponent(mid)+(i?'?retry='+Date.now():''));if(d?.match){last=d;if((d.servers||[]).length)return d}}
    catch(e){last=null}
    if(i+1<attempts)await new Promise(r=>setTimeout(r,550*(i+1)));
  }
  return last;
}
