function playStreamServer(server,onFail){const frame=document.querySelector('#embedPlayer'),video=document.querySelector('#video'),status=document.querySelector('#playerStatus');if(window.__hls){window.__hls.destroy();window.__hls=null}if(video){video.pause?.();video.removeAttribute('src');video.load?.();video.hidden=true}if(frame){frame.src='about:blank';frame.hidden=true}if(!server){if(status)status.innerHTML='<div>Siaran live untuk pertandingan ini belum tersedia. Sistem akan mencoba lagi saat server provider tersedia.</div>';return}if(server.type==='embed'&&server.embedUrl){if(status)status.textContent='';if(frame){frame.src=server.embedUrl;frame.hidden=false}return}if(video)video.hidden=false;let usedFallback=false;const fail=()=>{if(!usedFallback&&server.fallbackUrl&&server.fallbackUrl!==server.playUrl){usedFallback=true;if(status)status.textContent='Mencoba jalur streaming cadangan...';return playHls(server.fallbackUrl,onFail)}onFail?.()};playHls(server.playUrl||'',fail)}
