function setupAds(matchId,skipTop=false){
  const applies=a=>a.active&&(a.matchId==='all'||!a.matchId||String(a.matchId)===String(matchId));
  const top=state.boot.ads.find(a=>applies(a)&&a.placement==='top');
  const overlay=state.boot.ads.find(a=>applies(a)&&a.placement==='overlay');
  if(!skipTop&&top?.media){
    const box=document.createElement('a');box.className='live-top-ad';box.href=top.clickUrl||'#';box.target='_blank';box.rel='noopener';
    box.innerHTML=`${top.type==='video'?`<video src="${esc(top.media)}" autoplay muted loop playsinline preload="metadata"></video>`:`<img src="${esc(top.media)}" alt="${esc(top.title||'Iklan')}" loading="eager">`}<small>ADS</small>`;
    document.querySelector('.player')?.before(box)
  }
  if(!overlay?.media)return;
  const delay=Math.max(0,Number(overlay.delay||0))*1000;
  setTimeout(()=>{
    const el=document.querySelector('#ad');if(!el)return;
    el.className='ad-overlay sarang-video-ad';
    const media=overlay.type==='video'
      ?`<video class="sarang-ad-media" src="${esc(overlay.media)}" autoplay muted playsinline preload="auto"></video>`
      :`<img class="sarang-ad-media" src="${esc(overlay.media)}" alt="${esc(overlay.title||'Iklan')}">`;
    el.innerHTML=`<a class="sarang-ad-click" href="${esc(overlay.clickUrl||'#')}" target="_blank" rel="noopener">${media}</a><button class="sarang-ad-mute" type="button" aria-label="Suara">🔇</button><button class="sarang-ad-skip" type="button" disabled>Lewati dalam <b>5 detik</b></button>`;
    const video=el.querySelector('video'),mute=el.querySelector('.sarang-ad-mute'),skip=el.querySelector('.sarang-ad-skip');
    if(video&&mute){mute.onclick=e=>{e.preventDefault();video.muted=!video.muted;mute.textContent=video.muted?'🔇':'🔊'}}
    let left=Math.max(0,Math.min(60,Number(overlay.skipSeconds||5)||5));skip.innerHTML=left>0?`Lewati dalam <b>${left} detik</b>`:'Lewati Iklan <span>›</span>';if(left<=0){skip.disabled=false;skip.onclick=()=>el.remove()}
    const timer=setInterval(()=>{left-=1;if(!skip||!el.isConnected){clearInterval(timer);return}if(left<=0){clearInterval(timer);skip.disabled=false;skip.innerHTML='Lewati Iklan <span>›</span>';skip.onclick=()=>el.remove()}else skip.innerHTML=`Lewati dalam <b>${left} detik</b>`},1000);
    const duration=Math.max(8,Number(overlay.duration||20))*1000;
    setTimeout(()=>{if(el.isConnected)el.remove()},duration)
  },delay)
}
async function setupComments(mid){const list=document.querySelector('#comments');const d=await api('/api/comments/'+mid).catch(()=>({comments:[]}));d.comments.forEach(c=>addComment(c));const ioClient=await ensureSocket().catch(()=>null);const socket=ioClient?ioClient():null;if(socket){socket.emit('match:join',mid);socket.on('comment:new',addComment);socket.on('comment:delete',x=>document.querySelector(`[data-comment="${x.id}"]`)?.remove());socket.on('presence',x=>{const p=document.querySelector('#presence');if(p)p.textContent=x.count})}const commentForm=document.querySelector('#commentForm');if(commentForm)commentForm.onsubmit=async e=>{e.preventDefault();const input=e.target.querySelector('input');try{await api('/api/comments/'+mid,{method:'POST',body:JSON.stringify({text:input.value})});input.value=''}catch(err){alert(err.message)}};function addComment(c){if(document.querySelector(`[data-comment="${c.id}"]`))return;list.insertAdjacentHTML('beforeend',`<div class="comment" data-comment="${c.id}"><b>${esc(c.displayName)}</b><small> ${fmtTime(c.createdAt)}</small><div>${esc(c.text)}</div></div>`);list.scrollTop=list.scrollHeight}}
function highlightAdConfig(){return (state.boot.ads||[]).find(a=>a.active&&a.placement==='highlight'&&a.media)||null}
function mountSkippableAd(host,ad,onDone){
  if(!ad?.media)return onDone();
  const skipSeconds=Math.max(0,Math.min(60,Number(ad.skipSeconds||10)||10)),duration=Math.max(skipSeconds+2,Math.min(300,Number(ad.duration||30)||30));
  host.innerHTML=`<div class="highlight-ad-gate"><a href="${esc(ad.clickUrl||'#')}" target="_blank" rel="noopener" class="highlight-ad-media">${ad.type==='video'?`<video src="${esc(ad.media)}" autoplay muted playsinline preload="auto"></video>`:`<img src="${esc(ad.media)}" alt="${esc(ad.title||'Iklan')}">`}</a><button class="highlight-ad-mute" type="button" aria-label="Suara">🔇</button><button class="highlight-ad-skip" type="button" disabled>Lewati dalam <b>${skipSeconds} detik</b></button></div>`;
  const gate=host.querySelector('.highlight-ad-gate'),video=gate.querySelector('video'),mute=gate.querySelector('.highlight-ad-mute'),skip=gate.querySelector('.highlight-ad-skip');
  if(video)video.play().catch(()=>{});if(video&&mute)mute.onclick=e=>{e.preventDefault();e.stopPropagation();video.muted=!video.muted;mute.textContent=video.muted?'🔇':'🔊'};
  let left=skipSeconds,finished=false;const done=()=>{if(finished)return;finished=true;clearInterval(tick);clearTimeout(endTimer);onDone()};
  if(left<=0){skip.disabled=false;skip.innerHTML='Lewati Iklan <span>›</span>';skip.onclick=done}else{const tickFn=()=>{left--;if(left<=0){clearInterval(tick);skip.disabled=false;skip.innerHTML='Lewati Iklan <span>›</span>';skip.onclick=done}else skip.innerHTML=`Lewati dalam <b>${left} detik</b>`};var tick=setInterval(tickFn,1000)}
  var endTimer=setTimeout(done,duration*1000)
}
